import os

BASE_DIR = '/opt/data/cache/scratch/altakamul-site'

def patch_page(rel_path, replacements):
    fpath = os.path.join(BASE_DIR, rel_path)
    with open(fpath, 'r', encoding='utf-8') as f:
        c = f.read()
    count = 0
    for old, new in replacements:
        if old in c:
            c = c.replace(old, new)
            count += 1
        else:
            print(f"Warning: pattern not found in {rel_path}: {old[:35]}...")
    with open(fpath, 'w', encoding='utf-8') as f:
        f.write(c)
    print(f"Successfully patched {count}/{len(replacements)} nodes in {rel_path}!")

